// Pi 5 and scanner have real mounting chains and a native 3.3 V UART data link.
// Motor control, battery/regulation and scanner motor-control wiring remain unresolved; see README.md.
// Mechanical candidate; actual mounting interfaces are declared below.
Robot mount_ackermann_a2_mapping {
    intent "Raised planar mapping with A2"

    Ackermann chassis(ref = "hiwonder_ackermann_chassis")
    Motor motor_left(ref = "hiwonder_520_gearmotor_90_12v", glue = (-0.08607209, 0.06030475, 0.01400358, 0, 1, 0))
    Motor motor_right(ref = "hiwonder_520_gearmotor_90_12v", glue = (-0.08607209, -0.06026475, 0.01400358, 0, -1, 0))
    Standard wheel_front_left(ref = "hiwonder_ackermann_chassis_wheel", glue = (0.0856, 0.0845, 0.014, 0, 1, 0))
    Standard wheel_front_right(ref = "hiwonder_ackermann_chassis_wheel", glue = (0.0856, -0.0845, 0.014, 0, -1, 0))
    Standard wheel_rear_left(ref = "hiwonder_ackermann_chassis_wheel", glue = (-0.086, 0.0837, 0.014, 0, 1, 0))
    Standard wheel_rear_right(ref = "hiwonder_ackermann_chassis_wheel", glue = (-0.086, -0.0837, 0.014, 0, -1, 0))

    Mount device1_scanner_mount(ref = "robotdsl_ackermann_pi5_rplidar_tower", on = @core/chassis, at = "compute_ackermann_pi5", by = "under_holes")

    Lidar device1_scanner(ref = "husarion_rplidar_a2m12", on = @core/device1_scanner_mount, at = "scanner_holes", by = "mounting_holes", data = @core/computer, port = "uart0")

    Attachment computer(ref = "raspberry_pi_5_8gb", on = @core/device1_scanner_mount, at = "board_holes", by = "mounting_holes")
}

